import numpy as np
def fit(cols,y=None):
    y=dv_dt if y is None else y
    X=np.column_stack(cols); c,_,_,_=np.linalg.lstsq(X,y,rcond=None)
    return c, np.var(y-X@c)/np.var(y)
P=[np.ones_like(x),x,v,x**2,x*v,v**2,x**3,x**2*v,x*v**2,v**3]
